steps.fn:
() => {
 const id = '{{appId|js}}';
 if (!/^\d+$/.test(id) || location.hostname !== 'www.taptap.cn' || location.pathname !== '/app/' + id) throw new Error('当前页面不是请求的 TapTap 游戏详情');
 let game;
 for (const element of document.querySelectorAll('script[type="application/ld+json"]')) {
  try { const data = JSON.parse(element.textContent); if (data['@type'] === 'VideoGame') game = data; } catch {}
 }
 if (!game) throw new Error('TapTap 未提供游戏结构化数据，请检查验证页或页面变化');
 return {id, name: document.querySelector('h1').textContent.trim(), description: game.description, rating: game.aggregateRating?.ratingValue, ratingCount: game.aggregateRating?.ratingCount, reviewCount: game.aggregateRating?.reviewCount, ratingScale: game.aggregateRating?.bestRating, publisher: game.publisher, updatedAt: game.dateModified, url: location.href};
}
